def _is_dark_colour(colour) -> bool:
    """Whether white text reads better than black on ``colour`` --
    relative luminance, so a colour swatch button stays legible."""
    rgb = QColor(colour)
    if not rgb.isValid():
        return False
    return (0.299 * rgb.red() + 0.587 * rgb.green() + 0.114 * rgb.blue()) < 140

