class _PhaseFocusWatcher(QObject):
    """Watches clicks and focus in the Process panel: inside the Phase
    section the pivot line shows, on any other Process control it goes
    (user request, 2026-10-17). Clicks elsewhere (the plot, the list)
    leave it as it is, so zooming in to phase keeps the line."""

    _TYPES = (QEvent.Type.MouseButtonPress, QEvent.Type.FocusIn)

    def __init__(self, window):
        super().__init__(window)
        self._window = window

    def eventFilter(self, obj, event):  # noqa: N802 -- Qt override
        try:
            if event.type() in self._TYPES and isinstance(obj, QWidget):
                window = self._window
                panel = getattr(window, "_processing_panel_widget", None)
                content = getattr(window, "_phase_section_content", None)
                if panel is not None and content is not None and panel.isAncestorOf(obj):
                    section = getattr(window, "phase_section", None)
                    inside = (obj is content or content.isAncestorOf(obj)
                              or (section is not None and section.isAncestorOf(obj)))
                    window._set_phase_controls_active(inside)
        except RuntimeError:   # the window is being deleted
            pass
        return False


class _CompareArrowKeys(QObject):
    """Up/Down arrow keys reorder the highlighted Compare spectrum.

    Installed on the Compare list and on the Compare plot. While a
    spectrum is highlighted (clicked in the plot or selected in the
    list) a plain Up or Down moves it one place earlier/later in the
    plot order -- the same as Move Up / Move Down. With nothing
    highlighted the keys are left alone (so the list still scrolls).
    Shift/Ctrl/Alt + arrow are never taken, so extended selection and
    OS shortcuts keep working.
    """

    def __init__(self, window):
        super().__init__(window)
        self._window = window

    def eventFilter(self, obj, event):  # noqa: N802 -- Qt override
        if event.type() != QEvent.Type.KeyPress:
            return False
        key = event.key()
        window = self._window
        if key in (Qt.Key.Key_Delete, Qt.Key.Key_Backspace) and obj is window.compare_list:
            if window.compare_list.currentRow() < 0:
                return False
            window._on_remove_compare_clicked()
            return True
        if key not in (Qt.Key.Key_Up, Qt.Key.Key_Down):
            return False
        if event.modifiers() & (Qt.KeyboardModifier.ShiftModifier
                                | Qt.KeyboardModifier.ControlModifier
                                | Qt.KeyboardModifier.AltModifier
                                | Qt.KeyboardModifier.MetaModifier):
            return False
        window = self._window
        if window.compare_list.currentRow() < 0:
            return False
        window._on_move_compare_item(-1 if key == Qt.Key.Key_Up else 1)
        return True


class _ExperimentDropList(QListWidget):
    """The Compare list, accepting experiments dragged in from the Open
    experiments list (explicit user request).

    Emits :attr:`experimentsDropped` with the dragged session rows and
    the list row they were dropped on (-1 = after the last). The rows
    are read from the drag's own item-model payload rather than from the
    source list's selection, so what lands is exactly what was dragged.
    Drops that did not come from another list (files from the desktop,
    a drag started in this list) are refused."""

    experimentsDropped = Signal(list, int)
    _MIME = "application/x-qabstractitemmodeldatalist"

    def __init__(self, parent=None) -> None:
        super().__init__(parent)
        self.setAcceptDrops(True)
        self.setDropIndicatorShown(True)
        self.setDragDropMode(QAbstractItemView.DragDropMode.DropOnly)

    def _acceptable(self, event) -> bool:
        return event.mimeData().hasFormat(self._MIME) and event.source() is not self

    def clear_current(self) -> None:
        """No current row, nothing selected -- emits ``currentRowChanged(-1)``,
        which takes the highlight off the Compare plot."""
        self.clearSelection()
        self.setCurrentRow(-1)

    def mousePressEvent(self, event) -> None:  # noqa: N802 -- Qt override
        # A click on the list's blank space deselects, so the row tinted
        # on the Compare plot can be let go of from the list too (explicit
        # user request, 2026-10-15). Qt's own single-selection list keeps
        # its current row on such a click.
        if self.itemAt(event.position().toPoint()) is None:
            self.clear_current()
            event.accept()
            return
        super().mousePressEvent(event)

    def keyPressEvent(self, event) -> None:  # noqa: N802 -- Qt override
        if event.key() == Qt.Key.Key_Escape and self.currentRow() >= 0:
            self.clear_current()
            event.accept()
            return
        super().keyPressEvent(event)

    def dragEnterEvent(self, event) -> None:  # noqa: N802 -- Qt override
        if self._acceptable(event):
            event.setDropAction(Qt.DropAction.CopyAction)
            event.accept()
        else:
            event.ignore()

    def dragMoveEvent(self, event) -> None:  # noqa: N802 -- Qt override
        if self._acceptable(event):
            event.setDropAction(Qt.DropAction.CopyAction)
            event.accept()
        else:
            event.ignore()

    def dropEvent(self, event) -> None:  # noqa: N802 -- Qt override
        if not self._acceptable(event):
            event.ignore()
            return
        rows = self.rows_from_mime(event.mimeData())
        at = self.indexAt(event.position().toPoint()).row()
        event.setDropAction(Qt.DropAction.CopyAction)
        event.accept()
        if rows:
            self.experimentsDropped.emit(rows, at)

    @classmethod
    def rows_from_mime(cls, mime) -> list[int]:
        """Source rows in a QListWidget drag payload, in order, once each
        (shared with the plot's own drop target, which decodes the same
        payload when a 1D is dropped on a 2D's projection)."""
        from .widgets.canvas import _rows_from_list_drag
        return _rows_from_list_drag(mime, cls._MIME)


class _ExperimentSourceList(QListWidget):
    """The Open experiments list: a drag source that does not select.

    A plain ``QListWidget`` selects a row on mouse *press*, and selecting
    a row shows it on the Spectrum canvas -- so starting to drag a 1D
    onto a 2D's projection replaced the 2D with the 1D before the drag
    had even left the list, leaving nothing to drop onto. Real user
    report: "all that happens is that the 1-d spectrum I want to put on
    the projection appears in the Spectrum window".

    So a plain left press on a row is held back: moving past the drag
    distance starts a drag of that row (or of the whole selection, if
    the row is already part of it) with the selection and the plot
    untouched; releasing without moving replays the press, and it is an
    ordinary click. Presses with a modifier (Ctrl/Shift extending a
    selection), other buttons and the keyboard go straight to Qt as
    before. The drag also serves the Compare list, which it no longer
    disturbs either."""

    def __init__(self, parent=None) -> None:
        super().__init__(parent)
        self._pending_press = None  # (press event copy, row) while undecided

    def mousePressEvent(self, event) -> None:  # noqa: N802 -- Qt override
        self._pending_press = None
        if (event.button() == Qt.MouseButton.LeftButton
                and event.modifiers() == Qt.KeyboardModifier.NoModifier):
            index = self.indexAt(event.position().toPoint())
            if index.isValid():
                self._pending_press = (event.clone(), index.row())
                event.accept()
                return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event) -> None:  # noqa: N802 -- Qt override
        if self._pending_press is not None:
            press, row = self._pending_press
            if not (event.buttons() & Qt.MouseButton.LeftButton):
                self._pending_press = None
            elif ((event.position() - press.position()).manhattanLength()
                  >= QApplication.startDragDistance()):
                self._pending_press = None
                selected = sorted({i.row() for i in self.selectedIndexes()})
                rows = selected if row in selected else [row]
                self._start_drag(self.model().mimeData([self.model().index(r, 0) for r in rows]))
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event) -> None:  # noqa: N802 -- Qt override
        if self._pending_press is not None:
            press, _row = self._pending_press
            self._pending_press = None
            super().mousePressEvent(press)  # it was a click after all
        super().mouseReleaseEvent(event)

    def _start_drag(self, mime) -> None:
        """Run the drag. A seam of its own because a real ``QDrag``
        blocks in its own event loop, which a headless test cannot
        finish."""
        from PySide6.QtGui import QDrag
        drag = QDrag(self)
        drag.setMimeData(mime)
        drag.exec(Qt.DropAction.CopyAction)


def _launcher_icon(name: str) -> QIcon:
    """``QIcon`` for a side-panel launcher tile, or a null (empty)
    icon if the file is missing -- a missing icon file should never
    crash the GUI, just show a text-only button (WrappingTabWidget's
    own ``addTab`` already handles ``icon=None`` that way)."""
    path = os.path.join(_RESOURCES_DIR, name)
    return QIcon(path) if os.path.exists(path) else QIcon()


