    def _build_style_panel(self) -> QWidget:
        """Every plot-style and export control, as a plain widget.

        Was the Output *tab*; it is now the body of the Plot Style
        dialog (see :meth:`_on_plot_style_clicked`). The widgets
        themselves are unchanged and still live on ``self`` -- moving
        the panel rather than rebuilding it means every handler that
        reads ``self.output_*`` keeps working, and the change is where
        the controls live and what they act on, not what they are.

        Explicit user request: "maybe what we need is a plot view
        popup (from right click menu or top menu) that controls these
        things, rather than just the output tab... this supplants the
        need for an output tab"."""
        tab = QWidget()
        layout = QVBoxLayout(tab)

        self.style_scope_label = QLabel("")
        self.style_scope_label.setWordWrap(True)
        layout.addWidget(self.style_scope_label)

        # Collapsible sections (user request, 2026-10-20: one long list
        # broken up): Core styling (text, lines, ticks, colours), Legend,
        # Compare (gaps) and 2-D, then the lists of series and lines, Export
        # and Per-type defaults. Every control keeps its attribute name; a
        # row is placed in a section by ``section=`` on its addRow.
        style_box = QWidget()
        style_box_layout = QVBoxLayout(style_box)
        style_box_layout.setContentsMargins(0, 0, 0, 0)
        style_form = _SectionedForm(style_box_layout)
        style_form.add_section("Core styling", expanded=True)
        style_form.add_section("Axis limits")
        style_form.add_section("Insets")
        style_form.add_section("Legend")
        style_form.add_section("Compare")
        style_form.add_section("2-D")
        style_form.add_section("Electrochemistry")
        style_form.add_section("Data plots")
        self.style_sections = style_form.sections
        self._build_echem_style(style_form)
        self._build_other_data_style(style_form)

        self.output_linewidth_spin = QDoubleSpinBox()
        self.output_linewidth_spin.setRange(0.1, 10.0)
        self.output_linewidth_spin.setSingleStep(0.1)
        self.output_linewidth_spin.setValue(MplCanvas._AXIS_LINEWIDTH)
        self.output_linewidth_spin.valueChanged.connect(self._on_output_style_changed)
        style_form.addRow("Axis/spine linewidth:", self.output_linewidth_spin)

        self.output_fontsize_spin = TypedSpinBox()
        self.output_fontsize_spin.setRange(6, 40)
        self.output_fontsize_spin.setValue(MplCanvas._AXIS_LABELSIZE)
        self.output_fontsize_spin.valueChanged.connect(self._on_output_style_changed)
        style_form.addRow("Font size:", self.output_fontsize_spin)

        # --- Font family ------------------------------------------
        # matplotlib's generic families first (they resolve to something
        # on every machine), then every face matplotlib can draw with on
        # this one (explicit user request, 2026-10-17: more typefaces),
        # each shown in itself. notebook.fonts lists the same faces, so a
        # notebook and the GUI agree. A named face saved on another
        # computer that lacks it is kept and marked (see
        # _sync_output_style_controls), not silently swapped.
        self.output_font_family_combo = QComboBox()
        self.output_font_family_combo.addItem("Default", "")
        for family in nb_fonts.GENERIC_FAMILIES:
            self.output_font_family_combo.addItem(family, family)
        self.output_font_family_combo.insertSeparator(self.output_font_family_combo.count())
        # Each face is previewed in itself -- but only if Qt itself knows
        # it. matplotlib also lists faces Qt cannot load (macOS fonts that
        # are not installed locally, e.g. "Athelas"); asking Qt for one
        # makes it rebuild its whole font-alias table ("Populating font
        # family aliases took 80 ms. Replace uses of missing font family
        # 'Athelas'", seen in a user's terminal, 2026-10-20). Those stay in
        # the list, drawn in the menu font.
        qt_families = set(QFontDatabase.families())
        # matplotlib's own bundled faces (DejaVu ...) are not system fonts, so
        # Qt does not know them until they are loaded from the files.
        try:
            from pathlib import Path
            from matplotlib import font_manager, get_data_path
            bundled_dir = Path(get_data_path()) / "fonts" / "ttf"
            loaded = set()
            for entry in font_manager.fontManager.ttflist:
                if (entry.name not in qt_families and entry.fname not in loaded
                        and Path(entry.fname).parent == bundled_dir):
                    loaded.add(entry.fname)
                    QFontDatabase.addApplicationFont(str(entry.fname))
            if loaded:
                qt_families = set(QFontDatabase.families())
        except Exception:            # previews are cosmetic -- never block the window
            pass
        for family in nb_fonts.available_fonts():
            self.output_font_family_combo.addItem(family, family)
            if family in qt_families:
                self.output_font_family_combo.setItemData(
                    self.output_font_family_combo.count() - 1, QFont(family),
                    Qt.ItemDataRole.FontRole)
        self.output_font_family_combo.setMaxVisibleItems(20)
        self._narrow_combo(self.output_font_family_combo)
        self.output_font_family_combo.setToolTip(
            "Font family for every piece of text on the plot — title, axis "
            "labels, tick labels, the legend, and the maths in labels (¹³C, T₁).\n\n"
            "The generic families (sans-serif, serif, ...) look the same wherever "
            "the figure is made; a named face is one installed on this computer. "
            "Saved PDFs embed it, so the text stays editable in Illustrator; SVGs "
            "keep the letters as outlines, so they look the same without the font. "
            "Type a name's first letters to jump to it. “Default” leaves "
            "matplotlib's own choice alone."
        )
        self.output_font_family_combo.currentIndexChanged.connect(self._on_output_style_changed)
        style_form.addRow("Font family:", self.output_font_family_combo)

        # --- Axis label style ---------------------------------------
        # A chemical-shift axis label (built by NUC_label) defaults to
        # opennmr's own "brackets" form -- e.g. a rendered "delta 1H
        # (ppm)", fully mathregular -- rather than the older "delta
        # (1H) / ppm" some people still write in manuscripts. Explicit
        # user request: "People should be allowed to swap between
        # these or to even supply their own custom label if they
        # want." Non-nuclide unit labels ("Frequency (Hz)", etc.)
        # follow the same brackets/slash choice; see
        # MplCanvas._unit_label.
        self.output_axis_label_style_combo = QComboBox()
        self.output_axis_label_style_combo.addItem("Brackets: δ ¹H (ppm)", "brackets")
        self.output_axis_label_style_combo.addItem("Slash: δ (¹H) / ppm", "slash")
        self._narrow_combo(self.output_axis_label_style_combo)
        self.output_axis_label_style_combo.setToolTip(
            "How a chemical-shift axis label is written. Ignored while "
            "the custom label below has text in it."
        )
        self.output_axis_label_style_combo.currentIndexChanged.connect(self._on_output_style_changed)
        style_form.addRow("Axis label:", self.output_axis_label_style_combo)

        self.output_axis_label_template_edit = QLineEdit()
        self.output_axis_label_template_edit.setPlaceholderText(
            "Blank = automatic, e.g. {element}-{mass} shift ({unit})")
        self.output_axis_label_template_edit.setToolTip(
            "A fully custom chemical-shift axis label, overriding the "
            "choice above – leave blank to use it instead.\n\n"
            "Placeholders: {nuc} (\"1H\"), {mass} (\"1\"), {element} "
            "(\"H\"), {unit} (\"ppm\"). Plain text otherwise – include "
            "your own $...$ for mathtext if you want it."
        )
        self.output_axis_label_template_edit.editingFinished.connect(self._on_output_style_changed)
        style_form.addRow("Custom label:", self.output_axis_label_template_edit)

        # --- Title ------------------------------------------------
        # Off by default, on request. Several views set a title as they
        # draw (a slice number, a DOSY caption, the fitted peak); this
        # decides whether it is shown, not whether it is set.
        self.output_title_checkbox = QCheckBox("Show plot title")
        self.output_title_checkbox.setChecked(False)
        self.output_title_checkbox.setToolTip(
            "Show the title each view sets for itself — a slice number, a "
            "DOSY caption, the fitted peak's name.\n\n"
            "Off by default: a figure going into a manuscript is captioned "
            "there, and the on-plot title duplicates it."
        )
        self.output_title_checkbox.toggled.connect(self._on_output_style_changed)
        style_form.addRow(self.output_title_checkbox)

        # --- Contour levels ---------------------------------------
        # The same number the right-click "Set Contour Levels..." dialog
        # and the Relaxation tab's DOSY levels box set. Explicit user
        # request: "change number of contour levels directly (linked to
        # the other boxes where it might be used)".
        self.output_contour_levels_spin = TypedSpinBox()
        self.output_contour_levels_spin.setRange(2, 200)
        self.output_contour_levels_spin.setValue(MplCanvas._CONTOUR_CLEVELS_DEFAULT)
        self.output_contour_levels_spin.setToolTip(
            "How many contour rings are drawn, on a 2D map and a DOSY alike.\n\n"
            "The same setting as the right-click “Set Contour Levels…” dialog "
            "and the Relaxation tab's own DOSY levels box — changing it in any "
            "of them moves the others."
        )
        self.output_contour_levels_spin.valueChanged.connect(self._on_contour_levels_changed)
        style_form.addRow("Contour levels:", self.output_contour_levels_spin, section="2-D")

        # **How the levels are spaced, beside how many there are.**
        # The count alone decides nothing about whether a weak peak
        # next to a strong one is visible -- that is what the spacing
        # does -- so having one here and the other only behind a
        # right-click dialog split a single decision across two
        # places. User report: "the plot style for a 2D contour should
        # include number of contours and the power scaling".
        self.output_contour_mode_combo = QComboBox()
        self.output_contour_mode_combo.addItem("Power", "power")
        self.output_contour_mode_combo.addItem("Linear", "linear")
        self.output_contour_mode_combo.setToolTip(
            "How the contour levels are spaced between the noise floor and "
            "the tallest peak.\n\n"
            "Power bunches them towards the floor, which is what makes weak "
            "peaks beside a strong one visible; Linear spaces them evenly."
        )
        self.output_contour_mode_combo.currentIndexChanged.connect(
            lambda _i: self._on_contour_scaling_changed())
        style_form.addRow("Contour scaling:", self.output_contour_mode_combo, section="2-D")

        self.output_contour_power_spin = QDoubleSpinBox()
        self.output_contour_power_spin.setRange(0.1, 10.0)
        self.output_contour_power_spin.setSingleStep(0.05)
        self.output_contour_power_spin.setValue(MplCanvas._CONTOUR_POWER_DEFAULT)
        self.output_contour_power_spin.setToolTip(
            "Higher values bunch more levels near the noise floor — good for "
            "finding weak peaks near a strong one without saturating the "
            "display. Only used for Power scaling."
        )
        self.output_contour_power_spin.valueChanged.connect(
            lambda _v: self._on_contour_scaling_changed())
        style_form.addRow("Contour power:", self.output_contour_power_spin, section="2-D")

        self.output_tick_length_spin = QDoubleSpinBox()
        self.output_tick_length_spin.setRange(0.0, 20.0)
        self.output_tick_length_spin.setSingleStep(0.5)
        self.output_tick_length_spin.setValue(MplCanvas._TICK_LENGTH)
        self.output_tick_length_spin.valueChanged.connect(self._on_output_style_changed)
        style_form.addRow("Tick length:", self.output_tick_length_spin)

        self.output_tick_width_spin = QDoubleSpinBox()
        self.output_tick_width_spin.setRange(0.1, 10.0)
        self.output_tick_width_spin.setSingleStep(0.1)
        self.output_tick_width_spin.setValue(MplCanvas._TICK_WIDTH)
        self.output_tick_width_spin.valueChanged.connect(self._on_output_style_changed)
        style_form.addRow("Tick width:", self.output_tick_width_spin)

        # Explicit user request (2026-10-01): ticks in, out, or across
