        self.output_baseline_gap_spin = QDoubleSpinBox()
        self.output_baseline_gap_spin.setRange(0.0, 200.0)
        self.output_baseline_gap_spin.setDecimals(1)
        self.output_baseline_gap_spin.setSingleStep(1.0)
        self.output_baseline_gap_spin.setSuffix(" %")
        self.output_baseline_gap_spin.setValue(MplCanvas._BASELINE_GAP * 100.0)
        self.output_baseline_gap_spin.setToolTip(
            "Space between the lowest point of a 1D spectrum (or the bottom "
            "spectrum of a Compare) and the axis line, as a percentage of the "
            "trace's height. Measured from the trace's real minimum, so a "
            "baseline below zero is never drawn under the axis.")
        self.output_baseline_gap_spin.valueChanged.connect(self._on_output_style_changed)
        style_form.addRow("Gap below spectra:", self.output_baseline_gap_spin, section="Compare")

        # The spacing between stacked spectra is a draggable slider on the
        # Compare tile (Compare Controls ▸ Spacing) -- one control, one place.
        # It is still the widget Plot Style's saved per-type defaults read and
        # restore (``output_stack_gap_spin``, a percentage), just not shown here.
        self._ensure_spacing_slider()

        self.output_contour_fraction_spin = TypedSpinBox()
        self.output_contour_fraction_spin.setRange(1, 100)
        self.output_contour_fraction_spin.setValue(25)  # matches plotting.plot_2d_contour's own default (0.25)
        self.output_contour_fraction_spin.setSuffix("%")
        self.output_contour_fraction_spin.setToolTip(
            "How much of a 2D contour's own resolution renders by "
            "default (lower = faster, coarser) – doesn't affect "
            "a canvas currently set to Full Resolution (right-click "
            "the contour), or Save Figure As..., which always exports "
            "at true resolution regardless of this."
        )
        self.output_contour_fraction_spin.valueChanged.connect(self._on_contour_fraction_changed)
        style_form.addRow("2D downsample:", self.output_contour_fraction_spin, section="2-D")

        self.output_nq_line_checkbox = QCheckBox("Show diagonal (nQ) line")
        self.output_nq_line_checkbox.setToolTip(
            "Overlay a dashed y = n*x line on a 2D contour – n = 1 for "
            "the main diagonal (e.g. an EXSY/NOESY/COSY-style homonuclear "
            "correlation), or a higher n for a multiple-quantum "
            "correlation. plotting.plot_2d_contour's own show_nQ_line/nQ "
            "parameters – this is the GUI wiring for it."
        )
        self.output_nq_line_checkbox.toggled.connect(self._on_nq_line_changed)
        style_form.addRow(self.output_nq_line_checkbox, section="2-D")

        self.output_nq_value_spin = TypedSpinBox()
