    #: Optional sections that are off until switched on (Settings ▸ Sections
    #: shown, or a Welcome-wizard work type that uses them). Their choice is
    #: saved in ``shown_sections``; every other section's in
    #: ``hidden_sections`` (an empty list there still means "all shown").
    DEFAULT_HIDDEN_SECTIONS = ("pnmr",)

    #: The optional sections that live on the Apply tile. With none of
    #: them shown the tile has nothing on it, so it is hidden too.
    APPLY_TILE_SECTIONS = ("enmr", "imaging", "echem", "other_plot")

    def _apply_section_shown(self, key: str, shown: bool) -> None:
        for name in self.OPTIONAL_SECTIONS[key][1]:
            if name.startswith("tab:"):
                self._set_tile_shown(name[len("tab:"):], bool(shown))
                continue
            section = getattr(self, name, None)
            if section is not None:
                section.setVisible(bool(shown))
        if key in self.APPLY_TILE_SECTIONS:
            self._refresh_apply_tile()

    def _refresh_apply_tile(self) -> None:
        """Show the Apply tile (its button and Window-menu entry) only
        while at least one of its sections -- eNMR, Imaging -- is
        switched on in Settings; hide it when none is (explicit user
        request, 2026-10-21), and bring it back when either returns.
        Read from the sections themselves, not from the saved list, which
        is updated only after the sections are."""
        sections = [getattr(self, name, None)
                    for key in self.APPLY_TILE_SECTIONS
                    for name in self.OPTIONAL_SECTIONS[key][1]]
        sections = [section for section in sections if section is not None]
        if not sections:
            return
        self._set_tile_shown("Apply", any(not section.isHidden() for section in sections))

    def _set_tile_shown(self, label: str, shown: bool) -> None:
        """Show or hide a whole launcher tile: its button, its Window-menu
        entry, and -- if it is open -- leave it for Open."""
        for index in range(self.side_tabs.count()):
            if self.side_tabs.tabText(index) == label:
                if not shown and self.side_tabs.currentIndex() == index:
                    self._show_side_tab("Open")
                self.side_tabs.setTabVisible(index, shown)
        action = getattr(self, "_window_panel_actions", {}).get(label)
        if action is not None:
            action.setVisible(shown)
            action.setEnabled(shown)

    def _truncate_units(self) -> str:
        """"tdeff" (TopSpin's TDeff) or "points" (complex points after the
        filter): which Truncate to box is shown."""
        combo = getattr(self, "tdeff_unit_combo", None)
        return (combo.currentData() if combo is not None else None) or "tdeff"

    def _on_tdeff_unit_changed(self, remember: bool = True) -> None:
        """Show the Truncate to box in the chosen units, and remember the
        choice (``remember``: a user's choice, not the initial one)."""
        topspin = self._truncate_units() == "tdeff"
        self.tdeff_spin.setVisible(not topspin)
        self.tdeff_topspin_spin.setVisible(topspin)
        self._sync_tdeff_topspin()
        settings = getattr(self, "_ui_settings", None)
        if (remember and isinstance(settings, dict)
                and settings.get("truncate_units") != self._truncate_units()):
            settings["truncate_units"] = self._truncate_units()
            self._save_ui_settings()

    def _sync_tdeff_topspin(self) -> None:
        """Make the TDeff box show what the complex-point box holds."""
        box = getattr(self, "tdeff_topspin_spin", None)
        if box is None:
            return
        f = int(getattr(self, "_truncate_filter_points", 0) or 0)
        box.blockSignals(True)
        try:
            box.setMaximum(processing_ft.points_to_tdeff(self.tdeff_spin.maximum(), f))
            box.setValue(processing_ft.points_to_tdeff(self.tdeff_spin.value(), f))
        finally:
            box.blockSignals(False)
        box.setEnabled(self.tdeff_spin.isEnabled())

    def _on_tdeff_topspin_changed(self, tdeff: int) -> None:
        """A TDeff was typed: set the complex-point box from it (which is
        what reprocesses), then show the TDeff that actually means -- an
        odd number, or one inside the filter, rounds."""
        f = int(getattr(self, "_truncate_filter_points", 0) or 0)
        points = min(processing_ft.tdeff_to_points(tdeff, f), self.tdeff_spin.maximum())
        if points != self.tdeff_spin.value():
            self.tdeff_spin.setValue(points)
        self._sync_tdeff_topspin()

    def _show_truncate_units(self, spectrum, n_points: int, shown: bool) -> None:
        """Under Truncate to: how many points there are to truncate, in
        the box's units (complex points, after the digital filter), set
        against TopSpin's TD, which counts real *and* imaginary points
        and includes the filter's. Typing TD's 1024 for a 512-complex
        FID with a 78-point filter lands on the full 434 -- correct, but
        unexplained it read as the box resetting itself (user report,
        2026-10-15)."""
        acqus = (spectrum.metadata.raw or {}).get("acqus") or {}
        try:
            td = int(float(acqus.get("TD", 0) or 0))
        except (TypeError, ValueError):
            td = 0
        self._truncate_filter_points = (
            processing_ft.digital_filter_points(td, n_points)
            if shown and spectrum.metadata.vendor == "bruker" else 0)
        if not shown or n_points <= 0:
            self.tdeff_units_label.setVisible(False)
            return
        text = f"of {n_points} complex points"
        if td > 0 and spectrum.metadata.vendor == "bruker":
            complex_td = td // 2
            text += f" (TopSpin TD {td} = {complex_td} complex"
            removed = complex_td - n_points
            if removed > 0:
                text += f", less {removed} for the digital filter"
            text += ")"
        text += (". A larger value keeps the whole FID and pads it with zeros to that many "
                 "points (the FFT size grows to match if Zero-fill's is smaller).")
        self.tdeff_units_label.setText(text)
        self.tdeff_units_label.setVisible(True)

    def _show_recorded_tdeff_f1(self, spectrum, is_genuine_2d: bool, n1_native: int) -> None:
        """Under Truncate F1: TopSpin's own F1 TDeff, in its units and in
        increments, for a Bruker genuine 2D."""
        proc2s = (spectrum.metadata.raw or {}).get("proc2s") or {}
        try:
            tdeff = int(float(proc2s.get("TDeff", 0) or 0))
        except (TypeError, ValueError):
            tdeff = 0
        if not (is_genuine_2d and tdeff > 0):
            self.tdeff_f1_recorded_label.setVisible(False)
            return
        fn_mode = (spectrum.metadata.raw or {}).get("fn_mode")
        per = 2 if fn_mode in (4, 5, 6) else 1
        incr = tdeff // per
        text = (f"TopSpin: TDeff {tdeff} point{'s' if tdeff != 1 else ''}"
                + (f" = {incr} increments" if per == 2 else "")
                + ("  (every increment)" if incr >= n1_native else "")
                + (" – used by default." if incr < n1_native else "."))
        self.tdeff_f1_recorded_label.setText(text)
        self.tdeff_f1_recorded_label.setVisible(True)

    def _set_section_shown(self, key: str, shown: bool) -> None:
        """Show or hide one optional section (``OPTIONAL_SECTIONS``), and
        remember it in ``hidden_sections``."""
        shown = bool(shown)
        self._apply_section_shown(key, shown)
        box = self.section_shown_checkboxes.get(key)
        if box is not None and box.isChecked() != shown:
            box.blockSignals(True)
            box.setChecked(shown)
            box.blockSignals(False)
        hidden = [k for k in (self._ui_settings.get("hidden_sections") or [])
                  if k in self.OPTIONAL_SECTIONS and k != key]
        opted_in = [k for k in (self._ui_settings.get("shown_sections") or [])
                    if k in self.DEFAULT_HIDDEN_SECTIONS and k != key]
        if key in self.DEFAULT_HIDDEN_SECTIONS:
            if shown:
                opted_in.append(key)
        elif not shown:
            hidden.append(key)
        for name, keys in (("hidden_sections", hidden), ("shown_sections", opted_in)):
            if keys:
                self._ui_settings[name] = sorted(keys)
            else:
                self._ui_settings.pop(name, None)
        self._save_ui_settings()

    def _section_shown(self, key: str) -> bool:
        """Whether an optional section is shown: a default-hidden one only
        when switched on (``shown_sections``), any other unless switched
        off (``hidden_sections``)."""
        if key in self.DEFAULT_HIDDEN_SECTIONS:
            return key in (self._ui_settings.get("shown_sections") or [])
        return key not in (self._ui_settings.get("hidden_sections") or [])

    def _set_data_folder(self, folder: str) -> str:
        """Settings ▸ Data: the default data folder (``""`` = none).
        Saved; returns it. A file, or a folder that does not exist, is
        refused with a message and the previous choice kept."""
        folder = os.path.expanduser((folder or "").strip())
        if folder and not os.path.isdir(folder):
            QMessageBox.warning(self, "Default data folder",
                                f"{folder} is not a folder that exists.")
            folder = self._ui_settings.get("data_folder") or ""
        data_directory.set_default_data_directory(folder)
        if folder:
            self._ui_settings["data_folder"] = folder
        else:
            self._ui_settings.pop("data_folder", None)
        self._save_ui_settings()
        if self.data_folder_edit.text() != folder:
            self.data_folder_edit.setText(folder)
        self.statusBar().showMessage(
            f"Data dialogs will start in {folder}" if folder else "No default data folder.", 8000)
        return folder

    def _on_browse_data_folder(self) -> None:
        folder = QFileDialog.getExistingDirectory(
            self, "Default data folder",
            data_directory.default_data_directory() or os.path.expanduser("~"),
            options=QFileDialog.Option.DontUseNativeDialog)
        if folder:
            self._set_data_folder(folder)

    def _on_topspin_processing_toggled(self, checked: bool) -> None:
        self._ui_settings["topspin_processing_on_open"] = bool(checked)
        self._save_ui_settings()
        self.statusBar().showMessage(
            "Bruker data will open with TopSpin's processing." if checked else
            "Bruker data will open unprocessed (no phase, no window, every point) – "
            "experiments with saved openNMR processing still open as saved.", 8000)

    def _on_data_folder_browse_at_start_toggled(self, checked: bool) -> None:
        self._ui_settings["data_folder_browse_at_start"] = bool(checked)
        self._save_ui_settings()

    def _browse_default_data_folder(self) -> None:
        """Point the Open panel's browser at the default data folder
        (start-up, when Settings ▸ Data asks for it). Loads nothing."""
        directory = data_directory.default_data_directory()
        if not directory or not hasattr(self, "data_browser"):
            return
        self._browse_folder(directory)

    def _browse_folder(self, directory: str | None, full: bool = False) -> None:
        """List the experiments under ``directory`` in the Open panel.

        What was found there last time is shown at once (io.scan's
        remembered index); a scan then looks for what changed -- in the
        background, so the window never waits for it -- adds and removes
        experiments as it finds them, and remembers the result.
        ``full``: look through everything again (right-click ▸ Refresh).
        Synchronous when OPENNMR_BACKGROUND_SCAN=0 (tests)."""
        if not directory:
            return
        from . import folder_scan
        limit = self.SCAN_LIMIT
        if not folder_scan.background_scan_enabled():
            result = folder_scan.run_scan(directory, full=full, max_matches=limit)
            self.data_browser.set_matches(
                directory, result, truncated_at=limit if result.truncated else None,
                dates=result.dates)
            return
        remembered = io_scan.ScanIndex.load(directory)
        same_root = self.data_browser.root() is not None and \
            os.path.normcase(os.path.abspath(self.data_browser.root())) == \
            os.path.normcase(os.path.abspath(directory))
        if not same_root:
            self.data_browser.set_matches(
                directory, remembered.matches,
                truncated_at=limit if remembered.truncated else None, dates=remembered.dates)
        self._folder_scan_known = {path for path, _vendor in self.data_browser.matches()}
        first = not remembered.matches and not same_root
        self.data_browser.set_scan_status(
            "Looking for experiments in this folder…" if first else
            "Checking this folder for new or removed data…")
        if self._folder_scanner is None:
            self._folder_scanner = folder_scan.FolderScanner(self)
            self._folder_scanner.progress.connect(self._on_folder_scan_progress)
            self._folder_scanner.finished.connect(self._on_folder_scan_finished)
            self._folder_scanner.failed.connect(self._on_folder_scan_failed)
        self._folder_scanner.scan(directory, full=full, max_matches=limit)

    def _on_folder_scan_progress(self, root: str, folders: int, found) -> None:
        if root != self.data_browser.root():
            return
        # New experiments appear as they are found; nothing is taken
        # away until the scan has seen the whole folder.
        self.data_browser.update_matches(found, dates=getattr(found, "dates", None),
                                         remove_missing=False)
        self.data_browser.set_scan_status(
            f"Checking this folder… {folders:,} folders, {len(found):,} experiments so far.")

    def _on_folder_scan_finished(self, root: str, result) -> None:
        if root != self.data_browser.root():
            return
        self.data_browser.set_scan_status(None)
        if result.cancelled:
            self.data_browser.update_matches(result, dates=result.dates, remove_missing=False)
            self.statusBar().showMessage(
                "Stopped looking through the folder: some new or removed experiments may "
                "not be shown. Right-click the list ▸ Refresh to look again.", 10000)
            return
        added, removed = self.data_browser.update_matches(
            result, truncated_at=self.SCAN_LIMIT if result.truncated else None,
            dates=result.dates)
        new = len({path for path, _vendor in result} - self._folder_scan_known)
        if self._folder_scan_known and (new or removed):
            parts = []
            if new:
                parts.append(f"{new:,} new experiment{'s' if new != 1 else ''}")
            if removed:
                parts.append(f"{removed:,} no longer there")
            self.statusBar().showMessage(f"Data folder: {' and '.join(parts)}.", 8000)

    def _on_folder_scan_failed(self, root: str, message: str) -> None:
        if root != self.data_browser.root():
            return
        self.data_browser.set_scan_status(None)
        self.statusBar().showMessage(f"Could not look through {root}: {message}", 10000)

    def _on_folder_scan_stop(self) -> None:
        if self._folder_scanner is not None:
            self._folder_scanner.cancel()

    def _on_browse_state_folder(self) -> None:
        start = io_state.default_state_root()
        while start and not os.path.isdir(start):
            parent = os.path.dirname(start)
            start = parent if parent != start else ""
        folder = QFileDialog.getExistingDirectory(
            self, "Save openNMR states in", start or os.path.expanduser("~"),
            options=QFileDialog.Option.DontUseNativeDialog)
        if folder:
            self._set_state_folder(folder)

    def _on_show_state_folder(self) -> None:
        folder = io_state.default_state_root()
        try:
            os.makedirs(folder, exist_ok=True)
        except OSError as exc:
            QMessageBox.warning(self, "Show folder", f"Could not create {folder}:\n{exc}")
            return
        QDesktopServices.openUrl(QUrl.fromLocalFile(folder))

    def _on_fit_tolerance_changed(self, value) -> None:
        """Every fit from now on uses this convergence tolerance; saved."""
        value = core_fit_progress.set_tolerance(float(value))
        self._ui_settings["fit_tolerance"] = value
        self._save_ui_settings()

    def _on_fit_method_changed(self, value) -> None:
        """Every fit from now on uses this algorithm; saved."""
        value = core_fit_progress.set_method(value)
        self._ui_settings["fit_method"] = value
        self._save_ui_settings()
        self.statusBar().showMessage(
            f"Fitting algorithm: {core_fit_progress.METHODS[value]}.", 6000)

    def _on_max_iterations_changed(self, value: int) -> None:
        """Every fit from now on stops at ``value`` iterations; saved."""
        core_fit_progress.set_max_iterations(int(value))
        self._ui_settings["max_iterations"] = int(value)
        self._save_ui_settings()

    def _set_export_unit(self, unit: str, save: bool = True) -> None:
        """Settings ▸ Interface ▸ Export size in: "in" (default) or "cm"
        for Plot Style's figure width and height; remembered."""
        unit = unit if unit in LengthSpinBox.UNITS else "in"
        for spin in (self.output_fig_width_spin, self.output_fig_height_spin):
            spin.set_unit(unit)
        for canvas in self._all_canvases():
            canvas.export_length_unit = unit       # the Save Figure preview
        if self.export_unit_combo.currentData() != unit:
            blocked = self.export_unit_combo.blockSignals(True)
            self.export_unit_combo.setCurrentIndex(self.export_unit_combo.findData(unit))
            self.export_unit_combo.blockSignals(blocked)
        if save:
            self._ui_settings["export_unit"] = unit
            self._save_ui_settings()

    def _set_double_click_reset(self, on: bool, save: bool = True) -> None:
        """Settings ▸ Interface ▸ Double-click: reset the view, on every
        plot; remembered as ``double_click_reset``."""
        on = bool(on)
        for canvas in self._all_canvases():
            canvas.set_double_click_resets(on)
        if self.double_click_reset_checkbox.isChecked() != on:
            blocked = self.double_click_reset_checkbox.blockSignals(True)
            self.double_click_reset_checkbox.setChecked(on)
            self.double_click_reset_checkbox.blockSignals(blocked)
        if save:
            self._ui_settings["double_click_reset"] = on
            self._save_ui_settings()

    def _set_crosshair_style(self, color, width, save: bool = True) -> None:
        """Settings ▸ Interface ▸ Crosshair, or a plot's Crosshair-button
        menu: colour and line width on every plot; remembered as
        ``crosshair_color`` / ``crosshair_width``. A value the canvas
        rejects (a colour matplotlib cannot read, a width outside its
        range) leaves that part as it was."""
        for canvas in self._all_canvases():
            canvas.set_crosshair_style(color, width)
        color, width = self._all_canvases()[0].crosshair_style()
        swatch = QColor(matplotlib.colors.to_hex(color))
        self.crosshair_colour_button.setText(swatch.name())
        text_colour = "#000000" if swatch.lightness() > 128 else "#ffffff"
        self.crosshair_colour_button.setStyleSheet(
            f"background-color: {swatch.name()}; color: {text_colour};")
        blocked = self.crosshair_width_spin.blockSignals(True)
        self.crosshair_width_spin.setValue(width)
        self.crosshair_width_spin.blockSignals(blocked)
        if save:
            self._ui_settings["crosshair_color"] = color
            self._ui_settings["crosshair_width"] = width
            self._save_ui_settings()

    def _set_measure_style(self, color=None, width=None, fontsize=None, save: bool = True) -> None:
        """Settings ▸ Interface ▸ Measure, or a plot's Measure-button menu:
        colour, line width and text size on every plot; remembered as
        ``measure_color`` / ``measure_width`` / ``measure_fontsize``. A
        value the canvas rejects leaves that part as it was."""
        for canvas in self._all_canvases():
            canvas.set_measurement_style(color, width, fontsize)
        color, width, fontsize = self._all_canvases()[0].measurement_style()
        swatch = QColor(matplotlib.colors.to_hex(color))
        self.measure_colour_button.setText(swatch.name())
        text_colour = "#000000" if swatch.lightness() > 128 else "#ffffff"
        self.measure_colour_button.setStyleSheet(
            f"background-color: {swatch.name()}; color: {text_colour};")
        for spin, value in ((self.measure_width_spin, width),
                            (self.measure_fontsize_spin, fontsize)):
            blocked = spin.blockSignals(True)
            spin.setValue(value)
            spin.blockSignals(blocked)
        if save:
            self._ui_settings["measure_color"] = color
            self._ui_settings["measure_width"] = width
            self._ui_settings["measure_fontsize"] = fontsize
            self._save_ui_settings()

    def _on_measure_colour_clicked(self) -> None:
        color, _width, _size = self._all_canvases()[0].measurement_style()
